export function getUnitStrengthLabel(
  strengthUnit: UnitStrength | number | null | undefined
): string {
  if (strengthUnit == null) return "";
  return UnitStrengthDescription[strengthUnit as UnitStrength] ?? String(strengthUnit);
}

/** @deprecated Use UnitStrength */
export type Strength = UnitStrength;
/** @deprecated Use getUnitStrengthLabel */
export const getStrengthLabel = getUnitStrengthLabel;
/** @deprecated Use UNIT_STRENGTH_OPTIONS */
export const STRENGTH_OPTIONS = UNIT_STRENGTH_OPTIONS;
